	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		Actor actor = event.getActor();
		Actor target = local.getInteracting();
		if (actor == local || (target != null && actor == target) || event.getHitsplat().isMine())
		{
			lastCombatMs = System.currentTimeMillis();
			Actor named = actor == local ? target : actor;
			if (named instanceof NPC && named.getName() != null)
			{
				combatTarget = named.getName();
			}
		}
	}

	// ---------------------------------------------------------------- lifecycle plumbing

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// Posted on the EDT while the client closes: build the final batch on the client thread (like every
		// other batch), then let the client wait for the upload, which never waits through a retry window.
		XPTempoApi current = api;
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invoke(() ->
		{
			endSession("CLIENT_SHUTDOWN");
			current.flush().whenComplete((v, e) -> done.complete(null));
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!XPTempoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		api.configure(XPTempoApi.baseUrl(), config.apiKey());
		if (XPTempoConfig.KEY_API_KEY.equals(event.getKey()))
		{
			unlinkedHashes.clear(); // a new pairing may link an unlinked character back
		}
		if (XPTempoConfig.KEY_PAIRING_CODE.equals(event.getKey()))
		{
			maybePair();
		}
		if (XPTempoConfig.KEY_ENABLED.equals(event.getKey()) && config.enabled())
		{
			maybePair(); // a code pasted before switching on is used now
		}
		if (XPTempoConfig.KEY_ENABLED.equals(event.getKey()) || XPTempoConfig.KEY_API_KEY.equals(event.getKey()))
		{
			// Turning uploads on (or finishing pairing) mid-session: start a fresh session so the server gets the seed.
			clientThread.invoke(() ->
			{
				if (config.enabled() && api.isConfigured() && client.getGameState() == GameState.LOGGED_IN)
				{
					sessionId = null;
					initTicks = INIT_TICKS;
				}
				else if (!config.enabled())
				{
					stopUploads();
				}
			});
		}
		dropSwitchedOffCategory(event.getKey());
	}

	/** A category switch was turned off: what is waiting for it is dropped, not uploaded. */
	private void dropSwitchedOffCategory(String key)
	{
		List<String> types = new ArrayList<>();
		List<ContainerTracker.Kind> kinds = new ArrayList<>();
		if ("uploadInventory".equals(key) && !config.uploadInventory())
		{
			kinds.add(ContainerTracker.Kind.INVENTORY);
			kinds.add(ContainerTracker.Kind.EQUIPMENT);
		}
		else if ("uploadBank".equals(key) && !config.uploadBank())
		{
			kinds.add(ContainerTracker.Kind.BANK);
		}
		else if ("uploadGe".equals(key) && !config.uploadGe())
		{
			types.add("ge_offer");
		}
		else if ("uploadLoot".equals(key) && !config.uploadLoot())
		{
			types.add("loot");
			types.add("kill_count");
			types.add("counts");
		}
		if (types.isEmpty() && kinds.isEmpty())
		{
			return;
		}
		List<String> kindNames = new ArrayList<>();
		for (ContainerTracker.Kind k : kinds)
		{
			kindNames.add(k.name());
		}
		java.util.function.Predicate<Map<String, Object>> withdrawn = ev -> types.contains(String.valueOf(ev.get("type")))
			|| ("container".equals(ev.get("type")) && kindNames.contains(String.valueOf(ev.get("container"))));
		clientThread.invoke(() ->
		{
			kinds.forEach(containers::forget);
			pendingEvents.removeIf(withdrawn);
			api.dropQueuedEvents(withdrawn); // also from batches waiting in the offline queue
		});
	}

	/** Runs on the client thread two ticks after login/hop, when XP, the display name and GE slots are reliable. */
	private void seed()
	{
		long hash = client.getAccountHash();
		Player local = client.getLocalPlayer();
		if (hash == -1L || local == null || local.getName() == null)
		{
			initTicks = 1; // try again next tick
			return;
		}
		// Only the normal game: Leagues, Deadman, beta, Quest Speedrunning, PvP Arena and tournament characters
		// share the main's account hash but are separate characters, so they would overwrite the main's data.
		EnumSet<WorldType> types = client.getWorldType();
		RuneScapeProfileType profile = RuneScapeProfileType.getCurrent(client);
		boolean skipped = profile != RuneScapeProfileType.STANDARD;
		for (WorldType t : SKIPPED_WORLDS)
		{
			skipped |= types.contains(t);
		}
		if (skipped)
		{
			log.debug("XPTempo: not tracking on a {} world {}", profile, types);
			endSession("LOGOUT");
			return;
		}
		displayName = local.getName();
		world = client.getWorld();
		accountType = accountType(client.getVarbitValue(VarbitID.IRONMAN));
		long now = System.currentTimeMillis();
		boolean newSession = hash != accountHash || sessionId == null;
		if (newSession)
		{
			endSession("LOGOUT"); // a stale session for another character, if any
			accountHash = hash;
			sessionId = UUID.randomUUID().toString();
			sessionUploaded = false;
			seq = 0;
			tracker.reset();
			containers.reset();
			pendingEvents.clear();
			pendingEvents.add(event("session_start", now, "world", world));
			List<Map<String, Object>> rows = new ArrayList<>();
			for (Skill skill : Skill.values())
			{
				int xp = client.getSkillExperience(skill);
				int level = client.getRealSkillLevel(skill);
				tracker.seed(skill, xp, level);
				Map<String, Object> row = new LinkedHashMap<>();
				row.put("skill", skill.name());
				row.put("xp", xp);
				row.put("level", level);
				row.put("boosted", client.getBoostedSkillLevel(skill));
				rows.add(row);
			}
			pendingEvents.add(event("skills", now, "skills", rows));
			addMilestones(now);
			lastFlushMs = now;
			lastHeartbeatMs = now;
			urgent = true;
			log.debug("XPTempo: session {} started for {} on world {}", sessionId, displayName, world);
		}
		else
		{
			// World hop or reconnect: same character, same session; re-baseline silently.
			for (Skill skill : Skill.values())
			{
				tracker.seed(skill, client.getSkillExperience(skill), client.getRealSkillLevel(skill));
			}
		}
		// Current holdings and offers (the events for these were skipped during the init guard).
		if (config.uploadInventory())
		{
			offerContainer(ContainerTracker.Kind.INVENTORY, client.getItemContainer(InventoryID.INV));
			offerContainer(ContainerTracker.Kind.EQUIPMENT, client.getItemContainer(InventoryID.WORN));
		}
		if (config.uploadGe() && uploading())
		{
			GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			if (offers != null)
			{
				for (int slot = 0; slot < offers.length; slot++)
				{
					handleOffer(slot, offers[slot], now, newSession);
				}
			}
		}
	}

	private void flushXp(long now)
	{
		if (!tracker.hasPending())
		{
			return;
		}
		List<Map<String, Object>> deltas = new ArrayList<>();
		for (XpTracker.Delta d : tracker.drain())
		{
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("skill", d.skill.name());
			row.put("xpDelta", d.xpDelta);
			row.put("xp", d.xp);
			row.put("level", d.level);
			deltas.add(row);
		}
		pendingEvents.add(event("xp", now,
			"windowStart", iso(lastFlushMs),
			"windowEnd", iso(now),
			"deltas", deltas));
	}

	private void addHeartbeat(long now)
	{
		Map<String, Object> activity = new LinkedHashMap<>();
		Skill active = tracker.getActiveSkill();
		if (bankOpen)
		{
			activity.put("kind", "BANKING");
			activity.put("label", "Banking");
		}
		else if (geOpen)
		{
			activity.put("kind", "GRAND_EXCHANGE");
			activity.put("label", "At the Grand Exchange");
		}
		else if (now - lastCombatMs <= COMBAT_WINDOW_MS)
		{
			activity.put("kind", "COMBAT");
			activity.put("label", combatTarget != null ? "Fighting " + combatTarget : "In combat");
			if (active != null && now - tracker.getLastGainMs() <= ACTIVE_WINDOW_MS)
			{
				activity.put("skill", active.name());
			}
		}
		else if (active != null && now - tracker.getLastGainMs() <= ACTIVE_WINDOW_MS)
		{
			activity.put("kind", "SKILLING");
			activity.put("label", "Training " + active.getName());
			activity.put("skill", active.name());
		}
		else
		{
			activity.put("kind", "IDLE");
			activity.put("label", "Idle");
		}
		pendingEvents.add(event("heartbeat", now,
			"xpPerHour", tracker.xpPerHour(now),
			"activity", activity));
	}

	private synchronized void endSession(String reason)
	{
		if (sessionId == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		flushXp(now);
		// Inventory/bank changes still inside their debounce window would otherwise be lost at logout.
		emitContainer(containers.take(ContainerTracker.Kind.INVENTORY, now, 0, true), now);
		emitContainer(containers.take(ContainerTracker.Kind.EQUIPMENT, now, 0, true), now);
		emitContainer(containers.take(ContainerTracker.Kind.BANK, now, 0, true), now);
		pendingEvents.add(event("session_end", now, "reason", reason));
		sendBatch();
		sessionId = null;
		sessionUploaded = false;
		bankOpen = false;
		geOpen = false;
	}

	private synchronized void sendBatch()
	{
		urgent = false;
		if (pendingEvents.isEmpty())
		{
			return;
		}
		if (!uploading())
		{
			pendingEvents.clear(); // nothing leaves the client until the user opts in and pairs (or for an unlinked character)
			return;
		}
		Payloads.Batch batch = buildBatch(new ArrayList<>(pendingEvents));
		pendingEvents.clear();
		api.submit(batch);
	}

	/** Data can leave the client: the user switched XPTempo on, it is paired, and this character is not unlinked. */
	private boolean uploading()
	{
		return config.enabled() && api.isConfigured() && !unlinkedHashes.contains(accountHash);
	}

	private static long parseHash(Payloads.Batch batch)
	{
		try
		{
			return batch.account == null ? -1L : Long.parseLong(batch.account.hash);
		}
		catch (NumberFormatException e)
		{
			return -1L;
		}
	}

	private Payloads.Batch buildBatch(List<Map<String, Object>> events)
	{
		Payloads.Batch batch = new Payloads.Batch();
		batch.batchId = UUID.randomUUID().toString();
		batch.sentAt = iso(System.currentTimeMillis());
		batch.plugin = new Payloads.PluginInfo();
		batch.plugin.version = VERSION;
		batch.plugin.runelite = RuneLiteProperties.getVersion();
		batch.account = new Payloads.AccountInfo();
		batch.account.hash = Long.toString(accountHash);
		batch.account.displayName = displayName;
		batch.account.accountType = accountType;
		batch.account.world = world > 0 ? world : null;
		batch.sessionId = sessionId;
		batch.events = events;
		return batch;
	}

	/**
	 * "Enable XPTempo" was switched off: withdraw everything not yet uploaded and send only a session_end,
	 * so the server closes the session instead of counting it as still playing. Client thread only.
	 */
	private synchronized void stopUploads()
	{
		pendingEvents.clear();
		Payloads.Batch last = null;
		// A session_end only for a session the server knows about; nothing at all if this session never uploaded
		// (for example a key typed in while uploads are off).
		if (sessionId != null && sessionUploaded && api.isConfigured())
		{
			List<Map<String, Object>> events = new ArrayList<>();
			events.add(event("session_end", System.currentTimeMillis(), "reason", "PLUGIN_DISABLED"));
			last = buildBatch(events);
		}
		api.discardAllExcept(last);
		sessionId = null;
		sessionUploaded = false;
		bankOpen = false;
		geOpen = false;
	}

	/** Exchanges a pasted pairing code for a key. Nothing is sent to the server until "Enable XPTempo" is on. */
	private void maybePair()
	{
		String code = config.pairingCode().trim();
		if (pairing || code.isEmpty())
		{
			return;
		}
		if (!config.apiKey().trim().isEmpty())
		{
			configManager.setConfiguration(XPTempoConfig.GROUP, XPTempoConfig.KEY_PAIRING_CODE, "");
			chat("XPTempo: this RuneLite profile is already paired. To pair it with another account, clear the API key first.");
			return;
		}
		if (!config.enabled())
		{
			chat("XPTempo: turn on \"Enable XPTempo\" to pair with the code you pasted.");
			return;
		}
		pairing = true;
		api.pair(code, "RuneLite", response ->
		{
			configManager.setConfiguration(XPTempoConfig.GROUP, XPTempoConfig.KEY_API_KEY, response.apiKey);
			configManager.setConfiguration(XPTempoConfig.GROUP, XPTempoConfig.KEY_PAIRING_CODE, "");
			pairing = false;
			chat("XPTempo: paired with your XPTempo account. Every character you play on this RuneLite profile will sync to it.");
		}, error ->
		{
			pairing = false;
			chat("XPTempo: pairing failed (" + error + "). Get a fresh code from the app and try again.");
		});
	}

	private void chat(String message)
	{
		log.debug(message);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
			}
		});
	}

	private Map<String, Object> event(String type, long atMs, Object... keyValues)
	{
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("seq", ++seq);
		ev.put("at", iso(atMs));
		ev.put("type", type);
		for (int i = 0; i + 1 < keyValues.length; i += 2)
		{
			ev.put((String) keyValues[i], keyValues[i + 1]);
		}
		return ev;
	}

	private static String iso(long epochMs)
	{
		return Instant.ofEpochMilli(epochMs).toString();
	}

	/** VarbitID.IRONMAN values; 4–6 follow the Dink plugin's mapping (not defined by RuneLite itself). */
	private static String accountType(int ironman)
	{
		switch (ironman)
		{
			case 0:
				return "NORMAL";
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			case 6:
				return "UNRANKED_GROUP_IRONMAN";
			default:
				return "UNKNOWN";
		}
	}
}

package com.xptempo.api;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;
import java.util.function.Predicate;
import lombok.extern.slf4j.Slf4j;

/**
 * Bounded FIFO of unsent batches. While the API is unreachable the queue caps itself by merging two neighbouring
 * batches of the same character and session (never across characters or sessions, never the batch being sent):
 * XP deltas are summed per skill and superseded snapshots are dropped, so nothing the server needs is lost.
 */
@Slf4j
final class BatchQueue
{
	static final int MAX_BATCHES = 50;
	static final int MAX_EVENTS = 500;
	/** Never dropped when a merged batch has to be trimmed. */
	private static final Set<String> KEEP = Set.of("session_start", "session_end", "skills", "xp", "event", "ge_offer", "loot", "kill_count");
	/** What a session cannot do without; these survive even when a batch has to be cut down to fit. */
	private static final Set<String> SESSION = Set.of("session_start", "session_end", "skills");
	/** Only the newest of each matters, so older ones go first when trimming. */
	private static final Set<String> LATEST_ONLY = Set.of("heartbeat", "milestones", "counts");

	private final ArrayDeque<Payloads.Batch> queue = new ArrayDeque<>();
	/** The batch currently on the wire; it is never merged, split or dropped by add(). */
	private Payloads.Batch inFlight;
	/**
	 * A batch that was sent but got no clear answer (timeout, 5xx): the server may already have applied it, so it
	 * is only ever re-sent unchanged (same batchId, deduplicated server-side), never merged into a new batch.
	 */
	private Payloads.Batch attempted;

	synchronized void add(Payloads.Batch batch)
	{
		queue.addLast(batch);
		while (queue.size() > MAX_BATCHES)
		{
			if (!mergeOldestCompatiblePair())
			{
				dropOldestIdle();
			}
		}
	}

	/** The next batch to send, marked as in flight until {@link #release} or {@link #removeHead}. */
	synchronized Payloads.Batch take()
	{
		Payloads.Batch head = queue.peekFirst();
		if (head != null && head.events.size() > MAX_EVENTS)
		{
			// Safety net: never send more than the server accepts in one batch.
			queue.pollFirst();
			List<Payloads.Batch> chunks = new ArrayList<>();
			for (int i = 0; i < head.events.size(); i += MAX_EVENTS)
			{
				chunks.add(copyWithEvents(head, new ArrayList<>(head.events.subList(i, Math.min(head.events.size(), i + MAX_EVENTS)))));
			}
			for (int i = chunks.size() - 1; i >= 0; i--)
			{
				queue.addFirst(chunks.get(i));
			}
		}
		inFlight = queue.peekFirst();
		attempted = inFlight; // until the server answers, it may or may not have applied it
		return inFlight;
	}

	/** The send failed in a way the server may still have applied it; it stays at the head, to be re-sent unchanged. */
	synchronized void release(Payloads.Batch batch)
	{
		if (inFlight == batch)
		{
			inFlight = null;
		}
	}

	/** The send certainly did not reach the server (no connection, 429, 503): the batch may be changed or merged again. */
	synchronized void notApplied(Payloads.Batch batch)
	{
		if (attempted == batch)
		{
			attempted = null;
		}
		release(batch);
	}

	/** The server answered for this batch (accepted, or rejected for good). */
	synchronized void removeHead(Payloads.Batch batch)
	{
		if (queue.peekFirst() == batch)
		{
			queue.pollFirst();
		}
		if (attempted == batch)
		{
			attempted = null;
		}
		release(batch);
	}

	/** Replaces the head with two halves (HTTP 413). Returns false when the head cannot be split. */
	synchronized boolean splitHead(Payloads.Batch batch)
	{
		release(batch);
		if (attempted == batch)
		{
			attempted = null; // a 413 is refused before anything is applied
		}
		if (queue.peekFirst() != batch || batch.events.size() < 2)
		{
			return false;
		}
		queue.pollFirst();
		int mid = batch.events.size() / 2;
		Payloads.Batch second = copyWithEvents(batch, new ArrayList<>(batch.events.subList(mid, batch.events.size())));
		Payloads.Batch first = copyWithEvents(batch, new ArrayList<>(batch.events.subList(0, mid)));
		queue.addFirst(second);
		queue.addFirst(first);
		return true;
	}

	/**
	 * Uploads were switched off: drops everything not yet acknowledged, including the batch on the wire. If that
	 * request fails it is not retried; the inFlight reference stays so nothing merges with it until it returns.
	 */
	synchronized void clear()
	{
		queue.clear();
		attempted = null;
	}

	/**
	 * A category was switched off: removes its events from every queued batch except the one on the wire (and
	 * one awaiting a retry, which must be re-sent unchanged). Changed batches get a new id; empty ones go.
	 */
	synchronized void removeEvents(Predicate<Map<String, Object>> drop)
	{
		List<Payloads.Batch> list = new ArrayList<>(queue);
		queue.clear();
		for (Payloads.Batch b : list)
		{
			if (b == inFlight || b == attempted || b.events.stream().noneMatch(drop))
			{
				queue.addLast(b);
				continue;
			}
			List<Map<String, Object>> kept = new ArrayList<>();
			for (Map<String, Object> ev : b.events)
			{
				if (!drop.test(ev))
				{
					kept.add(ev);
				}
			}
			if (!kept.isEmpty())
			{
				queue.addLast(copyWithEvents(b, kept));
			}
		}
	}

	synchronized boolean isEmpty()
	{
		return queue.isEmpty();
	}

	synchronized int size()
	{
		return queue.size();
	}

	synchronized List<Payloads.Batch> snapshot()
	{
		return new ArrayList<>(queue);
	}

	private static boolean sameStream(Payloads.Batch a, Payloads.Batch b)
	{
		return a.account != null && b.account != null
			&& Objects.equals(a.account.hash, b.account.hash)
			&& Objects.equals(a.sessionId, b.sessionId);
	}

	/**
	 * Merges the oldest neighbouring pair of the same character and session whose result still fits the server's
	 * per-batch limit, skipping the batch on the wire and one awaiting a retry.
	 */
	private boolean mergeOldestCompatiblePair()
	{
		List<Payloads.Batch> list = new ArrayList<>(queue);
		for (int i = 0; i + 1 < list.size(); i++)
		{
			Payloads.Batch older = list.get(i);
			Payloads.Batch newer = list.get(i + 1);
			if (older == inFlight || newer == inFlight || older == attempted || newer == attempted || !sameStream(older, newer))
			{
				continue;
			}
			List<Map<String, Object>> events = new ArrayList<>(older.events);
			events.addAll(newer.events);
			List<Map<String, Object>> merged = trim(compactXp(events));
			if (merged.size() > MAX_EVENTS)
			{
				continue; // too many events that must be kept: leave this pair alone
			}
			list.set(i, copyWithEvents(newer, merged));
			list.remove(i + 1);
			queue.clear();
			queue.addAll(list);
			return true;
		}
		return false;
	}

	/**
	 * Last resort when no pair can be merged (alternating characters, or batches full of drops): drop the oldest
	 * batch not in flight. Its session_start and skills seed move to the next batch of the same session, so the
	 * server still opens that session.
	 */
	private void dropOldestIdle()
	{
		List<Payloads.Batch> list = new ArrayList<>(queue);
		for (int i = 0; i < list.size(); i++)
		{
			Payloads.Batch victim = list.get(i);
			if (victim == inFlight)
			{
				continue;
			}
			List<Map<String, Object>> carry = new ArrayList<>();
			for (Map<String, Object> ev : victim.events)
			{
				Object type = ev.get("type");
				if ("session_start".equals(type) || "skills".equals(type))
				{
					carry.add(ev);
				}
			}
			list.remove(i);
			if (!carry.isEmpty())
			{
				for (int j = i; j < list.size(); j++)
				{
					Payloads.Batch next = list.get(j);
					if (next != inFlight && next != attempted && sameStream(victim, next))
					{
						carry.addAll(next.events);
						list.set(j, copyWithEvents(next, fit(carry)));
						break;
					}
				}
			}
			if (victim == attempted)
			{
				attempted = null;
			}
			log.debug("XPTempo: offline queue full, dropped a batch of {} events", victim.events.size());
			queue.clear();
			queue.addAll(list);
			return;
		}
	}

	/** Cuts a batch down to MAX_EVENTS: trim first, then the oldest events other than the session's own. */
	private static List<Map<String, Object>> fit(List<Map<String, Object>> events)
	{
		List<Map<String, Object>> out = events.size() > MAX_EVENTS ? trim(events) : events;
		for (int i = 0; out.size() > MAX_EVENTS && i < out.size(); )
		{
			if (SESSION.contains(String.valueOf(out.get(i).get("type"))))
			{
				i++;
			}
			else
			{
				out.remove(i);
			}
		}
		return out;
	}

	/** Keeps a merged batch under MAX_EVENTS: superseded snapshots first, then the oldest droppable events. */
	static List<Map<String, Object>> trim(List<Map<String, Object>> events)
	{
		// Keep only the newest heartbeat/milestones/counts and the newest snapshot per container.
		Map<String, Integer> newest = new LinkedHashMap<>();
		for (int i = 0; i < events.size(); i++)
		{
			String key = supersedeKey(events.get(i));
			if (key != null)
			{
				newest.put(key, i);
			}
		}
		List<Map<String, Object>> out = new ArrayList<>();
		for (int i = 0; i < events.size(); i++)
		{
			String key = supersedeKey(events.get(i));
			if (key == null || newest.get(key) == i)
			{
				out.add(events.get(i));
			}
		}
		for (int i = 0; out.size() > MAX_EVENTS && i < out.size(); )
		{
			if (KEEP.contains(String.valueOf(out.get(i).get("type"))))
			{
				i++;
			}
			else
			{
				out.remove(i);
			}
		}
		return out;
	}

	private static String supersedeKey(Map<String, Object> ev)
	{
		String type = String.valueOf(ev.get("type"));
		if (LATEST_ONLY.contains(type))
		{
			return type + ("counts".equals(type) ? ":" + ev.get("interface") : "");
		}
		if ("container".equals(type))
		{
			return "container:" + ev.get("container");
		}
		return null;
	}

	/** Folds all xp events into one: deltas summed per skill, latest xp/level kept, window spans both. */
	@SuppressWarnings("unchecked")
	static List<Map<String, Object>> compactXp(List<Map<String, Object>> events)
	{
		Map<String, Map<String, Object>> deltasBySkill = new LinkedHashMap<>();
		String windowStart = null;
		String windowEnd = null;
		int seq = -1;
		String at = null;
		int insertAt = -1;
		List<Map<String, Object>> rest = new ArrayList<>();
		for (Map<String, Object> ev : events)
		{
			if (!"xp".equals(ev.get("type")))
			{
				rest.add(ev);
				continue;
			}
			if (insertAt < 0)
			{
				insertAt = rest.size();
			}
			String ws = (String) ev.get("windowStart");
			String we = (String) ev.get("windowEnd");
			if (windowStart == null || ws.compareTo(windowStart) < 0)
			{
				windowStart = ws;
			}
			if (windowEnd == null || we.compareTo(windowEnd) > 0)
			{
				windowEnd = we;
				at = (String) ev.get("at");
				seq = ((Number) ev.get("seq")).intValue();
			}
			for (Map<String, Object> d : (List<Map<String, Object>>) ev.get("deltas"))
			{
				String skill = (String) d.get("skill");
				Map<String, Object> merged = deltasBySkill.get(skill);
				if (merged == null)
				{
					deltasBySkill.put(skill, new LinkedHashMap<>(d));
				}
				else
				{
					int sum = ((Number) merged.get("xpDelta")).intValue() + ((Number) d.get("xpDelta")).intValue();
					merged.put("xpDelta", sum);
					merged.put("xp", d.get("xp"));
					merged.put("level", d.get("level"));
				}
			}
		}
		if (deltasBySkill.isEmpty())
		{
			return rest;
		}
		Map<String, Object> xp = new LinkedHashMap<>();
		xp.put("seq", seq);
		xp.put("at", at);
		xp.put("type", "xp");
		xp.put("windowStart", windowStart);
		xp.put("windowEnd", windowEnd);
		xp.put("deltas", new ArrayList<>(deltasBySkill.values()));
		rest.add(insertAt, xp);
		return rest;
	}

	/** A merged or split batch is a new payload, so it gets a new id (never reuse an id with a different body). */
	private static Payloads.Batch copyWithEvents(Payloads.Batch src, List<Map<String, Object>> events)
	{
		Payloads.Batch b = new Payloads.Batch();
		b.batchId = UUID.randomUUID().toString();
		b.sentAt = src.sentAt;
		b.plugin = src.plugin;
		b.account = src.account;
		b.sessionId = src.sessionId;
		b.events = events;
		return b;
	}
}

package com.xptempo.api;

import java.util.List;
import java.util.Map;

/** JSON shapes of the XPTempo ingest API (POST /v1/ingest, POST /v1/pair), serialised with RuneLite's Gson. */
public final class Payloads
{
	private Payloads()
	{
	}

	public static final class Batch
	{
		public String batchId;
		public String sentAt;
		public PluginInfo plugin;
		public AccountInfo account;
		public String sessionId;
		public List<Map<String, Object>> events;
	}

	public static final class PluginInfo
	{
		public String version;
		public String runelite;
	}

	public static final class AccountInfo
	{
		/** Client.getAccountHash() as a decimal string (a Java long does not survive JSON number parsing). */
		public String hash;
		public String displayName;
		public String accountType;
		public Integer world;
	}

	public static final class PairRequest
	{
		public String code;
		public String clientName;
	}

	public static final class PairResponse
	{
		public String apiKey;
		public String keyPrefix;
		public String userEmail;
	}

	public static final class Ack
	{
		public String batchId;
		public int accepted;
		public int duplicates;
		public List<Rejection> rejected;
		public String serverTime;
		public CadenceConfig config;
		/** "account_unlinked": the player unlinked this character in the app, so the server stored nothing. */
		public String notice;
	}

	public static final class Rejection
	{
		public int seq;
		public String code;
		public String message;
	}

	public static final class CadenceConfig
	{
		public int heartbeatSeconds;
		public int xpFlushSeconds;
		public int inventoryDebounceSeconds;
		public int bankMaxEverySeconds;
		public int maxBatchEvents;
		public int maxBatchBytes;
	}

	public static final class ApiError
	{
		public ErrorBody error;
	}

	public static final class ErrorBody
	{
		public String code;
		public String message;
	}
}

package com.xptempo.api;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.net.ConnectException;
import java.net.NoRouteToHostException;
import java.net.UnknownHostException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Predicate;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * HTTP client for the XPTempo API. Every call is asynchronous (OkHttp enqueue) and never runs on the client
 * thread. Batches are sent one at a time in order; failures retry the same batch (same batchId, so the server
 * can deduplicate) with exponential back-off from 5 s to 5 min plus jitter. There is only ever one retry timer,
 * new batches wait for it, and a backlog is sent at a gentle pace once the server answers again.
 */
@Slf4j
public final class XPTempoApi
{
	public interface Listener
	{
		/** The server answered for this batch; `sent` is the batch the ack belongs to. */
		void onAck(Payloads.Batch sent, Payloads.Ack ack);

		void onUnauthorized();

		void onFailure(String message, boolean willRetry);
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final long BASE_BACKOFF_MS = 5_000L;
	private static final long MAX_BACKOFF_MS = 300_000L;
	/** Gap between batches while catching up on a backlog, so recovering servers are not flooded. */
	private static final long BACKLOG_GAP_MS = 750L;

	private final OkHttpClient http;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final Listener listener;
	private final BatchQueue queue = new BatchQueue();
	private final String userAgent;

	private volatile HttpUrl baseUrl;
	private volatile String apiKey = "";
	private volatile boolean paused;
	private volatile boolean closed;
	private boolean sending;
	private int failures;
	/**
	 * No send before this time (the single retry timer, or the pause between backlog batches). Monotonic, on the
	 * same clock as the executor's timer, so a wall-clock adjustment can never strand a wake-up.
	 */
	private long notBeforeMs;
	private ScheduledFuture<?> wakeUp;
	private CompletableFuture<Void> drained;

	public XPTempoApi(OkHttpClient base, Gson gson, ScheduledExecutorService executor, String userAgent, Listener listener)
	{
		// Derive from RuneLite's shared client (Hub rule: never construct your own); only the call timeout changes.
		this.http = base.newBuilder().callTimeout(15, TimeUnit.SECONDS).build();
		this.gson = gson;
		this.executor = executor;
		this.userAgent = userAgent;
		this.listener = listener;
	}

	/** Where every player's plugin sends data. Fixed: the service lives at api.xptempo.com. */
	public static final String PRODUCTION_BASE_URL = "https://api.xptempo.com";

	/**
	 * The production address. A developer running the plugin from source can point it at an API on their own
	 * machine with -Dxptempo.api=http://127.0.0.1:3000; any other host is ignored, so data only ever goes to
	 * api.xptempo.com or the developer's own computer.
	 */
	public static String baseUrl()
	{
		String override = System.getProperty("xptempo.api");
		HttpUrl url = override == null ? null : HttpUrl.parse(override.trim());
		boolean local = url != null && ("127.0.0.1".equals(url.host()) || "localhost".equals(url.host()));
		return local ? url.toString() : PRODUCTION_BASE_URL;
	}

	/** Called at start-up and whenever the config changes. A new key un-pauses sending after a 401. */

	public void configure(String baseUrlText, String apiKey)
	{
		HttpUrl parsed = HttpUrl.parse(baseUrlText == null ? "" : baseUrlText.trim());
		this.baseUrl = parsed;
		String key = apiKey == null ? "" : apiKey.trim();
		if (!key.equals(this.apiKey))
		{
			this.apiKey = key;
			this.paused = false;
			executor.execute(this::sendNext);
		}
	}

	public boolean isConfigured()
	{
		return baseUrl != null && !apiKey.isEmpty();
	}

	public int queuedBatches()
	{
		return queue.size();
	}

	/** Exchanges a pairing code for an API key (no auth; the code is single-use). */
	public void pair(String code, String clientName, Consumer<Payloads.PairResponse> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = baseUrl;
		if (url == null)
		{
			onError.accept("API base URL is not valid");
			return;
		}
		Payloads.PairRequest body = new Payloads.PairRequest();
		body.code = code;
		body.clientName = clientName;
		Request request = new Request.Builder()
			.url(url.newBuilder().addPathSegments("v1/pair").build())
			.header("User-Agent", userAgent)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept("could not reach the XPTempo API: " + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					String text = bodyText(r.body());
					if (r.isSuccessful())
					{
						onSuccess.accept(gson.fromJson(text, Payloads.PairResponse.class));
					}
					else
					{
						onError.accept(errorMessage(r.code(), text));
					}
				}
				catch (IOException | JsonSyntaxException e)
				{
					onError.accept("bad response from the XPTempo API: " + e.getMessage());
				}
			}
		});
	}

	public void submit(Payloads.Batch batch)
	{
		if (closed)
		{
			return;
		}
		queue.add(batch);
		executor.execute(this::sendNext);
	}

	/**
	 * Uploads were switched off: forget everything not yet sent and send only this last batch (the
	 * session_end), so the server stops counting the session. Null just clears the queue.
	 */
	public void discardAllExcept(Payloads.Batch last)
	{
		queue.clear();
		if (last != null)
		{
			submit(last);
		}
	}

	/** A category was switched off: its events leave every queued batch that has not been attempted yet. */
	public void dropQueuedEvents(Predicate<Map<String, Object>> drop)
	{
		queue.removeEvents(drop);
	}

	/** The plugin is shutting down: stop retrying, drop the queue, ignore further submissions. */
	public void close()
	{
		ScheduledFuture<?> timer;
		synchronized (this)
		{
			closed = true;
			timer = wakeUp;
			wakeUp = null;
		}
		if (timer != null)
		{
			timer.cancel(false);
		}
		queue.clear();
		completeDrainedIfIdle();
	}

	/** For ClientShutdown: completes when the queue is empty, paused, or the next attempt fails. */
	public CompletableFuture<Void> flush()
	{
		CompletableFuture<Void> future = new CompletableFuture<>();
		synchronized (this)
		{
			drained = future;
		}
		executor.execute(this::sendNext);
		return future;
	}

	private void sendNext()
	{
		Payloads.Batch batch;
		Request request;
		synchronized (this)
		{
			if (closed || sending || paused || queue.isEmpty() || !isConfigured())
			{
				completeDrainedIfIdle();
				return;
			}
			long wait = notBeforeMs - nowMs();
			// While the client waits to shut down, a backlog goes out without the pacing gap (but never early in a back-off).
			if (wait > 0 && !(failures == 0 && drained != null))
			{
				// Backing off or pacing: one timer wakes the queue, new batches just wait for it.
				schedule(wait);
				if (failures > 0 && drained != null)
				{
					drained.complete(null); // never hold the client's shutdown for a retry window
					drained = null;
				}
				return;
			}
			batch = queue.take();
			if (batch == null)
			{
				completeDrainedIfIdle(); // emptied by an opt-out between the checks
				return;
			}
			request = new Request.Builder()
				.url(baseUrl.newBuilder().addPathSegments("v1/ingest").build())
				.header("Authorization", "Bearer " + apiKey)
				.header("User-Agent", userAgent)
				.post(RequestBody.create(JSON, gson.toJson(batch)))
				.build();
			sending = true;
		}
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				// No connection was made, so the server cannot have applied it: it may be changed or merged again.
				boolean neverArrived = e instanceof ConnectException || e instanceof UnknownHostException || e instanceof NoRouteToHostException;
				if (neverArrived)
				{
					queue.notApplied(batch);
				}
				else
				{
					queue.release(batch);
				}
				scheduleRetry("network error: " + e.getMessage(), -1);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				int code;
				String text;
				long retryAfterMs = -1;
				try (Response r = response)
				{
					code = r.code();
					text = bodyText(r.body());
					String retryAfter = r.header("Retry-After");
					if (retryAfter != null)
					{
						try
						{
							retryAfterMs = Long.parseLong(retryAfter.trim()) * 1000L;
						}
						catch (NumberFormatException ignored)
						{
							// not a delay in seconds; use the normal back-off
						}
					}
				}
				catch (IOException e)
				{
					queue.release(batch);
					scheduleRetry("could not read response: " + e.getMessage(), -1);
					return;
				}
				handleResponse(batch, code, text, retryAfterMs);
			}
		});
	}

	/** Every branch clears `sending` in the same locked step that records the outcome, so no send can slip in between. */
	private void handleResponse(Payloads.Batch batch, int code, String text, long retryAfterMs)
	{
		if (code >= 200 && code < 300)
		{
			boolean moreAfter = queue.size() > 1;
			queue.removeHead(batch);
			synchronized (this)
			{
				sending = false;
				// Catching up after an outage: space the backlog out (with jitter) instead of sending it all at once,
				// unless the client is waiting to shut down.
				boolean pace = (failures > 0 || moreAfter) && !queue.isEmpty() && drained == null;
				failures = 0;
				notBeforeMs = pace ? nowMs() + BACKLOG_GAP_MS + ThreadLocalRandom.current().nextLong(BACKLOG_GAP_MS) : 0;
			}
			try
			{
				Payloads.Ack ack = gson.fromJson(text, Payloads.Ack.class);
				if (ack != null)
				{
					listener.onAck(batch, ack);
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("XPTempo: unreadable ack: {}", e.getMessage());
			}
			executor.execute(this::sendNext);
			return;
		}
		if (code == 401)
		{
			queue.release(batch);
			synchronized (this)
			{
				sending = false;
				paused = true;
			}
			listener.onUnauthorized();
			completeDrainedIfIdle();
			return;
		}
		if (code == 413)
		{
			synchronized (this)
			{
				sending = false;
			}
			if (!queue.splitHead(batch))
			{
				queue.removeHead(batch);
				listener.onFailure("batch too large and cannot be split; dropped", false);
			}
			executor.execute(this::sendNext);
			return;
		}
		if (code == 429 || code >= 500)
		{
			if (code == 429 || code == 503)
			{
				queue.notApplied(batch); // refused before anything was applied
			}
			else
			{
				queue.release(batch);
			}
			scheduleRetry(errorMessage(code, text), retryAfterMs);
			return;
		}
		// Any other 4xx: the batch itself is unacceptable; drop it rather than block the queue forever.
		synchronized (this)
		{
			sending = false;
		}
		queue.removeHead(batch);
		listener.onFailure(errorMessage(code, text) + "; batch dropped", false);
		executor.execute(this::sendNext);
	}

	private void scheduleRetry(String message, long retryAfterMs)
	{
		long delay;
		synchronized (this)
		{
			sending = false;
			if (closed)
			{
				return;
			}
			failures++;
			int shift = Math.min(failures - 1, 6);
			long base = retryAfterMs > 0 ? Math.min(MAX_BACKOFF_MS, retryAfterMs) : Math.min(MAX_BACKOFF_MS, BASE_BACKOFF_MS << shift);
			// Jitter on top (also of Retry-After), so thousands of clients do not come back in the same second.
			delay = base + ThreadLocalRandom.current().nextLong(base / 4 + 1);
			notBeforeMs = nowMs() + delay;
			schedule(delay);
			// Never hold the client's shutdown hook for a retry window.
			if (drained != null)
			{
				drained.complete(null);
				drained = null;
			}
		}
		listener.onFailure(message + " (retrying in " + (delay / 1000) + " s)", true);
	}

	/** Arms the single wake-up timer (replacing an earlier, later one). Caller holds the lock. */
	private void schedule(long delayMs)
	{
		if (closed)
		{
			return;
		}
		if (wakeUp != null && !wakeUp.isDone())
		{
			long remaining = wakeUp.getDelay(TimeUnit.MILLISECONDS);
			if (remaining > 0 && remaining <= delayMs)
			{
				return; // an earlier wake-up is already armed (a timer that is firing right now does not count)
			}
			wakeUp.cancel(false);
		}
		ScheduledFuture<?>[] self = new ScheduledFuture<?>[1];
		self[0] = executor.schedule(() ->
		{
			synchronized (XPTempoApi.this)
			{
				if (wakeUp == self[0])
				{
					wakeUp = null;
				}
			}
			sendNext();
		}, delayMs, TimeUnit.MILLISECONDS);
		wakeUp = self[0];
	}

	private static long nowMs()
	{
		return System.nanoTime() / 1_000_000L;
	}

	private void completeDrainedIfIdle()
	{
		CompletableFuture<Void> toComplete = null;
		synchronized (this)
		{
			if (drained != null && (closed || queue.isEmpty() || paused || !isConfigured()))
			{
				toComplete = drained;
				drained = null;
			}
		}
		if (toComplete != null)
		{
			toComplete.complete(null);
		}
	}

	private String errorMessage(int code, String text)
	{
		try
		{
			Payloads.ApiError err = gson.fromJson(text, Payloads.ApiError.class);
			if (err != null && err.error != null && err.error.message != null)
			{
				return "HTTP " + code + " " + err.error.code + ": " + err.error.message;
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// not our error shape
		}
		return "HTTP " + code;
	}

	private static String bodyText(ResponseBody body) throws IOException
	{
		return body == null ? "" : body.string();
	}
}

package com.xptempo.tracker;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.TreeMap;
import java.util.zip.CRC32;

/**
 * Keeps the latest snapshot of each container and decides when it is worth sending: only when the
 * contents changed since the last send, and no more often than the per-container interval.
 * Pure logic; the plugin feeds it canonicalised item ids.
 */
public final class ContainerTracker
{
	public enum Kind
	{
		INVENTORY, BANK, EQUIPMENT
	}

	public static final class Snapshot
	{
		public final Kind kind;
		/** [itemId, quantity] pairs, ids ascending, duplicates summed. */
		public final List<int[]> items;
		public final String hash;

		Snapshot(Kind kind, List<int[]> items, String hash)
		{
			this.kind = kind;
			this.items = items;
			this.hash = hash;
		}
	}

	private final EnumMap<Kind, Snapshot> pending = new EnumMap<>(Kind.class);
	private final EnumMap<Kind, String> lastSentHash = new EnumMap<>(Kind.class);
	private final EnumMap<Kind, Long> lastSentMs = new EnumMap<>(Kind.class);

	/** Drops empty slots (id ≤ 0) and placeholders (quantity ≤ 0), sums duplicate ids, sorts by id. */
	public static Snapshot snapshot(Kind kind, int[] ids, int[] quantities)
	{
		TreeMap<Integer, Long> merged = new TreeMap<>();
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] <= 0 || quantities[i] <= 0)
			{
				continue;
			}
			merged.merge(ids[i], (long) quantities[i], Long::sum);
		}
		List<int[]> items = new ArrayList<>(merged.size());
		CRC32 crc = new CRC32();
		for (var e : merged.entrySet())
		{
			int qty = (int) Math.min(Integer.MAX_VALUE, e.getValue());
			items.add(new int[]{e.getKey(), qty});
			int id = e.getKey();
			crc.update(id); // CRC32.update(int) takes only the low byte, so feed all four bytes of id and quantity
			crc.update(id >>> 8);
			crc.update(id >>> 16);
			crc.update(id >>> 24);
			crc.update(qty);
			crc.update(qty >>> 8);
			crc.update(qty >>> 16);
			crc.update(qty >>> 24);
		}
		return new Snapshot(kind, items, Long.toHexString(crc.getValue()) + ":" + items.size());
	}

	/** Records the latest contents; nothing becomes pending if they match what was last sent. */
	public void offer(Snapshot snapshot)
	{
		if (snapshot.hash.equals(lastSentHash.get(snapshot.kind)))
		{
			pending.remove(snapshot.kind);
		}
		else
		{
			pending.put(snapshot.kind, snapshot);
		}
	}

	public boolean hasPending(Kind kind)
	{
		return pending.containsKey(kind);
	}

	/**
	 * Returns the pending snapshot and marks it sent when one exists and the interval since the last
	 * send has elapsed (or force is set); otherwise null.
	 */
	public Snapshot take(Kind kind, long nowMs, long minIntervalMs, boolean force)
	{
		Snapshot s = pending.get(kind);
		if (s == null)
		{
			return null;
		}
		Long last = lastSentMs.get(kind);
		if (!force && last != null && nowMs - last < minIntervalMs)
		{
			return null;
		}
		pending.remove(kind);
		lastSentMs.put(kind, nowMs);
		lastSentHash.put(kind, s.hash);
		return s;
	}

	/** A category was switched off: drop what is waiting, and send a full snapshot if it is switched on again. */
	public void forget(Kind kind)
	{
		pending.remove(kind);
		lastSentHash.remove(kind);
		lastSentMs.remove(kind);
	}

	/** Forget everything (new character / new session): the server will get full payloads again. */
	public void reset()
	{
		pending.clear();
		lastSentHash.clear();
		lastSentMs.clear();
	}
}

package com.xptempo.tracker;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns GrandExchangeOfferChanged into ingest events with a stable client offer id per offer.
 * Mirrors the core GE plugin's "saved offer per slot" trick: the last known offer of each slot is
 * persisted (RS-profile config), so a restart or the login burst never mints a second id for the
 * same offer, and a slot going EMPTY after a finished offer becomes a "collected" update.
 */
public final class GeOfferTracker
{
	/** Persisted per slot (Gson). Field names are part of the saved format; do not rename. */
	public static final class SavedOffer
	{
		public String clientOfferId;
		public int itemId;
		public long price;
		public int totalQuantity;
		public int quantitySold;
		public long spent;
		public String state; // ACTIVE | COMPLETED | CANCELLED
		public String type;  // BUY | SELL
	}

	public interface Store
	{
		SavedOffer load(int slot);

		void save(int slot, SavedOffer offer);

		void clear(int slot);
	}

	private final Store store;
	private final Supplier<String> idGenerator;

	public GeOfferTracker(Store store, Supplier<String> idGenerator)
	{
		this.store = store;
		this.idGenerator = idGenerator;
	}

	/** Returns the `ge_offer` event fields to send, or null when nothing changed. */
	public Map<String, Object> onOffer(int slot, GrandExchangeOffer offer)
	{
		return onOffer(slot, offer, false);
	}

	/**
	 * As {@link #onOffer(int, GrandExchangeOffer)}; with force, an unchanged non-empty slot is reported anyway
	 * (a new session re-sends every open offer, so offers placed before uploads were switched on are not missed;
	 * the server upserts by clientOfferId).
	 */
	public Map<String, Object> onOffer(int slot, GrandExchangeOffer offer, boolean force)
	{
		GrandExchangeOfferState rlState = offer.getState();
		SavedOffer saved = store.load(slot);
		if (rlState == GrandExchangeOfferState.EMPTY)
		{
			if (saved == null)
			{
				return null;
			}
			// The slot was emptied: a finished offer was collected, or an active one was cancelled and
			// collected between two observations.
			String finalState = saved.state;
			if ("ACTIVE".equals(saved.state))
			{
				finalState = saved.quantitySold >= saved.totalQuantity ? "COMPLETED" : "CANCELLED";
			}
			saved.state = finalState;
			store.clear(slot);
			return fields(slot, saved, true);
		}

		String type = isBuy(rlState) ? "BUY" : "SELL";
		String state = mapState(rlState);
		boolean sameOffer = saved != null
			&& saved.itemId == offer.getItemId()
			&& saved.price == offer.getPrice()
			&& saved.totalQuantity == offer.getTotalQuantity()
			&& type.equals(saved.type)
			&& offer.getQuantitySold() >= saved.quantitySold;
		boolean changed;
		if (!sameOffer)
		{
			saved = new SavedOffer();
			saved.clientOfferId = idGenerator.get();
			saved.itemId = offer.getItemId();
			saved.price = offer.getPrice();
			saved.totalQuantity = offer.getTotalQuantity();
			saved.type = type;
			changed = true;
		}
		else
		{
			changed = saved.quantitySold != offer.getQuantitySold()
				|| saved.spent != offer.getSpent()
				|| !state.equals(saved.state);
		}
		saved.quantitySold = offer.getQuantitySold();
		saved.spent = offer.getSpent();
		saved.state = state;
		store.save(slot, saved);
		return changed || force ? fields(slot, saved, false) : null;
	}

	private static Map<String, Object> fields(int slot, SavedOffer o, boolean collected)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("clientOfferId", o.clientOfferId);
		m.put("slot", slot);
		m.put("itemId", o.itemId);
		m.put("offerType", o.type);
		m.put("price", o.price);
		m.put("totalQuantity", o.totalQuantity);
		m.put("quantitySold", o.quantitySold);
		m.put("spent", o.spent);
		m.put("state", o.state);
		m.put("collected", collected);
		return m;
	}

	static boolean isBuy(GrandExchangeOfferState s)
	{
		return s == GrandExchangeOfferState.BUYING || s == GrandExchangeOfferState.BOUGHT
			|| s == GrandExchangeOfferState.CANCELLED_BUY;
	}

	static String mapState(GrandExchangeOfferState s)
	{
		switch (s)
		{
			case BUYING:
			case SELLING:
				return "ACTIVE";
			case BOUGHT:
			case SOLD:
				return "COMPLETED";
			default:
				return "CANCELLED";
		}
	}
}

package com.xptempo.tracker;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Accumulates XP gains per skill between flushes. Pure logic, no client access, so it is unit-testable.
 * All methods are called on the client thread (or under the plugin's lock during shutdown).
 */
public final class XpTracker
{
	/** One skill's gain over a flush window plus its absolute XP/level at the end of the window. */
	public static final class Delta
	{
		public final Skill skill;
		public final int xpDelta;
		public final int xp;
		public final int level;

		Delta(Skill skill, int xpDelta, int xp, int level)
		{
			this.skill = skill;
			this.xpDelta = xpDelta;
			this.xp = xp;
			this.level = level;
		}
	}

	public static final class LevelUp
	{
		public final Skill skill;
		public final int level;
		public final int xp;

		LevelUp(Skill skill, int level, int xp)
		{
			this.skill = skill;
			this.level = level;
			this.xp = xp;
		}
	}

	private static final long RATE_WINDOW_MS = 10 * 60_000L;

	private final EnumMap<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private final EnumMap<Skill, Integer> lastLevel = new EnumMap<>(Skill.class);
	private final EnumMap<Skill, Integer> pending = new EnumMap<>(Skill.class);
	/** {timeMs, delta} pairs for the rolling XP/hr figure. */
	private final Deque<long[]> recent = new ArrayDeque<>();
	private Skill activeSkill;
	private long lastGainMs;

	public void reset()
	{
		lastXp.clear();
		lastLevel.clear();
		pending.clear();
		recent.clear();
		activeSkill = null;
		lastGainMs = 0;
	}

	/** Sets the baseline for a skill without recording a gain (login seed, world hop). */
	public void seed(Skill skill, int xp, int level)
	{
		lastXp.put(skill, xp);
		lastLevel.put(skill, level);
	}

	public boolean isSeeded()
	{
		return !lastXp.isEmpty();
	}

	/**
	 * Records a StatChanged. Returns a LevelUp when the real level rose, otherwise null.
	 * Boost/drain events (same xp) record nothing.
	 */
	public LevelUp record(Skill skill, int xp, int level, long nowMs)
	{
		Integer prevXp = lastXp.put(skill, xp);
		Integer prevLevel = lastLevel.put(skill, level);
		if (prevXp == null)
		{
			return null; // first sight: baseline only
		}
		int delta = xp - prevXp;
		if (delta > 0)
		{
			pending.merge(skill, delta, Integer::sum);
			recent.addLast(new long[]{nowMs, delta});
			activeSkill = skill;
			lastGainMs = nowMs;
		}
		// A real level only rises together with XP; anything else is a boost, a drain or a stale read.
		if (delta > 0 && prevLevel != null && level > prevLevel)
		{
			return new LevelUp(skill, level, xp);
		}
		return null;
	}

	public boolean hasPending()
	{
		return !pending.isEmpty();
	}

	public Skill getActiveSkill()
	{
		return activeSkill;
	}

	public long getLastGainMs()
	{
		return lastGainMs;
	}

	/** Moves the accumulated gains out as deltas and clears them. */
	public List<Delta> drain()
	{
		List<Delta> out = new ArrayList<>(pending.size());
		for (Map.Entry<Skill, Integer> e : pending.entrySet())
		{
			Skill s = e.getKey();
			out.add(new Delta(s, e.getValue(), lastXp.getOrDefault(s, 0), lastLevel.getOrDefault(s, 1)));
		}
		pending.clear();
		return out;
	}

	/**
	 * XP gained over the last ten minutes, scaled to an hour. Early in a session the span is the time since
	 * the first gain (never less than a minute), so the figure is not diluted by time before training began.
	 */
	public int xpPerHour(long nowMs)
	{
		while (!recent.isEmpty() && recent.peekFirst()[0] < nowMs - RATE_WINDOW_MS)
		{
			recent.pollFirst();
		}
		if (recent.isEmpty())
		{
			return 0;
		}
		long sum = 0;
		for (long[] r : recent)
		{
			sum += r[1];
		}
		long spanMs = Math.max(60_000L, Math.min(RATE_WINDOW_MS, nowMs - recent.peekFirst()[0]));
		return (int) Math.min(Integer.MAX_VALUE, sum * 3_600_000L / spanMs);
	}
}

package com.xptempo;

import com.xptempo.tracker.ContainerTracker;
import com.xptempo.tracker.ContainerTracker.Kind;
import com.xptempo.tracker.ContainerTracker.Snapshot;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ContainerTrackerTest
{
	@Test
	public void snapshotDropsEmptySlotsAndPlaceholdersAndMergesStacks()
	{
		Snapshot s = ContainerTracker.snapshot(Kind.INVENTORY,
			new int[]{-1, 4151, 536, 4151, 995, 1234},
			new int[]{0, 1, 27, 1, 1_000_000, 0});
		assertEquals(3, s.items.size());
		assertArrayEquals(new int[]{536, 27}, s.items.get(0));
		assertArrayEquals(new int[]{995, 1_000_000}, s.items.get(1));
		assertArrayEquals(new int[]{4151, 2}, s.items.get(2));
	}

	@Test
	public void unchangedContentsAreNotPendingAndIntervalsAreHonoured()
	{
		ContainerTracker t = new ContainerTracker();
		Snapshot a = ContainerTracker.snapshot(Kind.INVENTORY, new int[]{536}, new int[]{27});
		t.offer(a);
		assertTrue(t.hasPending(Kind.INVENTORY));
		assertNotNull(t.take(Kind.INVENTORY, 1_000, 60_000, false));
		assertFalse(t.hasPending(Kind.INVENTORY));

		t.offer(ContainerTracker.snapshot(Kind.INVENTORY, new int[]{536}, new int[]{27})); // same hash
		assertFalse(t.hasPending(Kind.INVENTORY));

		Snapshot b = ContainerTracker.snapshot(Kind.INVENTORY, new int[]{536}, new int[]{26});
		t.offer(b);
		assertNull(t.take(Kind.INVENTORY, 30_000, 60_000, false));   // too soon
		assertNotNull(t.take(Kind.INVENTORY, 30_000, 60_000, true)); // forced (bank close)
		assertNull(t.take(Kind.INVENTORY, 61_001, 60_000, false));   // nothing pending any more
	}

	@Test
	public void itemIdsThatShareTheirLowByteHashDifferently()
	{
		// 861 (magic shortbow) and 1373 (rune battleaxe) are both 0x5D in their low byte.
		ContainerTracker.Snapshot a = ContainerTracker.snapshot(ContainerTracker.Kind.INVENTORY, new int[]{861}, new int[]{1});
		ContainerTracker.Snapshot b = ContainerTracker.snapshot(ContainerTracker.Kind.INVENTORY, new int[]{1373}, new int[]{1});
		org.junit.Assert.assertNotEquals(a.hash, b.hash);
	}

	@Test
	public void forgettingACategoryDropsItsPendingSnapshotAndResendsLater()
	{
		ContainerTracker t = new ContainerTracker();
		ContainerTracker.Snapshot s = ContainerTracker.snapshot(ContainerTracker.Kind.BANK, new int[]{995}, new int[]{100});
		t.offer(s);
		org.junit.Assert.assertNotNull(t.take(ContainerTracker.Kind.BANK, 0, 0, true));
		t.offer(s);
		org.junit.Assert.assertFalse(t.hasPending(ContainerTracker.Kind.BANK)); // unchanged, nothing to send
		t.forget(ContainerTracker.Kind.BANK);
		t.offer(s);
		org.junit.Assert.assertTrue(t.hasPending(ContainerTracker.Kind.BANK)); // after a switch-off, a fresh snapshot goes again
	}
}

package com.xptempo;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DiaryVarpsTest
{
	/** Must match `varps` in the XPTempo API's diary table; the server rejects any other id. */
	private static final int[] SERVER_VARPS = {
		1000, 1001, 1002, 1176, 1177, 1178, 1179, 1180, 1181, 1182, 1183, 1184, 1185, 1186, 1187,
		1188, 1189, 1190, 1191, 1192, 1193, 1194, 1195, 1196, 1197, 1198, 1199, 1200, 2085, 2086,
	};

	@Test
	public void sendsExactlyTheVarpsTheServerDecodes()
	{
		int[] sent = DiaryVarps.VARPS.clone();
		Arrays.sort(sent);
		assertArrayEquals(SERVER_VARPS, sent);
		assertEquals(30, Arrays.stream(sent).distinct().count());
	}

	@Test
	public void tracksTaskAndCountVarpsOnly()
	{
